"""Aggregate workers and retire live gauges when a worker dies."""
import os
from pathlib import Path
import shutil

from prometheus_client import multiprocess


def child_exit(server, worker):
    multiprocess.mark_process_dead(worker.pid)


def on_exit(server):
    # Only the private directory generated by start_api.sh is ours to delete.
    directory = Path(os.environ.get("PROMETHEUS_MULTIPROC_DIR", ""))
    if directory.name.startswith("edgelab-metrics.") and not directory.is_symlink():
        shutil.rmtree(directory, ignore_errors=True)
